// Package override builds the text of a generated docker-compose.override.yml.
package override

import (
	"fmt"
	"regexp"
	"strings"
)

// Marker is the comment that identifies a docker-compose.override.yml as
// having been generated by this tool. It must stay byte-for-byte identical
// to the original compose-worktree-override shell function's marker, since
// existing override files on disk are guarded by this exact string.
const Marker = "# generated by compose-worktree-override"

// PortLine is one resolved `ports:` list entry, ready to render as a YAML
// sequence item.
type PortLine struct {
	// Content is the entry's YAML content, without the leading "- " or any
	// indentation. For short syntax this is the plain "host:container"
	// string (Build quotes it as a scalar). For long syntax this is
	// already-rendered, possibly multi-line YAML mapping text (Build emits
	// it verbatim, indenting continuation lines to align under the first).
	Content string
	// Long is true when Content is a long-syntax mapping rather than a
	// short-syntax scalar string.
	Long bool
}

// Service is one service's resolved override: the container_name to set
// (empty if none) and the ports lines to emit (nil if the service has no
// ports to override).
type Service struct {
	Name          string
	ContainerName string
	HasPorts      bool
	Ports         []PortLine
}

// projectNameChars matches the characters docker compose allows in a
// project name.
var projectNameChars = regexp.MustCompile(`[a-z0-9_-]+`)

// ProjectName normalizes raw into a valid compose project name (lowercase
// alphanumerics, "-" and "_", starting with an alphanumeric). It applies
// the same rule docker compose itself uses to derive the default project
// name from a directory name - lowercase, drop every other character, trim
// leading "-"/"_" - so a main worktree, whose raw name is just its
// directory name, keeps the project name it had before this tool set one.
// It returns "" when nothing valid is left.
func ProjectName(raw string) string {
	name := strings.Join(projectNameChars.FindAllString(strings.ToLower(raw), -1), "")
	return strings.TrimLeft(name, "_-")
}

// Build renders the override file contents: the top-level compose project
// name (omitted when projectName is "") followed by the given services, in
// the order provided. It returns "" if there is neither a project name nor
// any service with something to override.
func Build(projectName string, services []Service) string {
	var any bool
	for _, s := range services {
		if s.ContainerName != "" || s.HasPorts {
			any = true
			break
		}
	}
	if projectName == "" && !any {
		return ""
	}

	var b strings.Builder
	b.WriteString(Marker + "\n")
	if projectName != "" {
		// Quoted so an all-digit or otherwise YAML-special name (123,
		// true, null) still reaches compose as the string it requires.
		fmt.Fprintf(&b, "name: %q\n", projectName)
	}
	if !any {
		return b.String()
	}
	b.WriteString("services:\n")

	for _, s := range services {
		if s.ContainerName == "" && !s.HasPorts {
			continue
		}

		fmt.Fprintf(&b, "  %s:\n", s.Name)

		if s.ContainerName != "" {
			fmt.Fprintf(&b, "    container_name: %s\n", s.ContainerName)
		}

		if s.HasPorts {
			// docker compose merges (concatenates) list-typed keys across
			// override files by default, so without !override the
			// original, un-namespaced ports would still be exposed
			// alongside the reassigned ones (Compose 2.24+).
			b.WriteString("    ports: !override\n")
			for _, p := range s.Ports {
				writeSequenceItem(&b, p)
			}
		}
	}

	return b.String()
}

// writeSequenceItem writes one `ports:` list entry at the fixed 6-space
// indentation `Build` uses for the list. Long-syntax entries are
// potentially multi-line; every line after the first is indented two
// spaces further, to align under the content following "- ".
func writeSequenceItem(b *strings.Builder, p PortLine) {
	if !p.Long {
		fmt.Fprintf(b, "      - %q\n", p.Content)
		return
	}

	lines := strings.Split(strings.TrimRight(p.Content, "\n"), "\n")
	fmt.Fprintf(b, "      - %s\n", lines[0])
	for _, line := range lines[1:] {
		fmt.Fprintf(b, "        %s\n", line)
	}
}
